import 'package:flutter/material.dart'; import '../../core/theme/app_theme.dart';
class RequestScreen extends StatefulWidget { const RequestScreen({super.key}); @override State<RequestScreen> createState()=>_RequestScreenState(); } class _RequestScreenState extends State<RequestScreen>{final form=GlobalKey<FormState>(); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Request a song')),body:Padding(padding:const EdgeInsets.all(20),child:Form(key:form,child:Column(children:[for(final label in ['Song title','Artist','Dedication']) Padding(padding:const EdgeInsets.only(bottom:14),child:TextFormField(decoration:InputDecoration(labelText:label,border:const OutlineInputBorder()),validator:(v)=>label!='Dedication'&&(v==null||v.trim().isEmpty)?'Please enter $label':null)),const Spacer(),FilledButton(style:FilledButton.styleFrom(backgroundColor:AppColors.crimson,minimumSize:const Size.fromHeight(52)),onPressed:(){if(form.currentState!.validate())ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Your song request is pending review.')));},child:const Text('REQUEST SONG'))])));}
